        isHistorical: false,
        feedback: 'آستیاگ قصد حمله‌ی پیشگیرانه به انشان را داشت. اطلاعات تاریخی نشان می‌دهد که آستیاگ پیش از دریافت نامه‌ی هارپاگ، به فکر سرکوب پارسیان بود. انفعال کوروش فقط به سرکوب پارسی‌ها می‌انجامید. ابتکار عمل کوروش، سرنوشت کل منطقه را بازنویسی کرد.',
        wisdomGain: 10,
