    legacy:
      'پیروزی کوروش بر ماد، اولین قدم در ساخت بزرگ‌ترین امپراتوری دنیای باستان بود. تنها ۱۱ سال بعد، کوروش لیدی (ترکیه‌ی امروزی) را فتح کرد. ۹ سال بعد، بابل را بدون جنگ تسخیر کرد و یهودیان اسیر را آزاد کرد. دخترش آتوسا با داریوش بزرگ ازدواج کرد و پسرش کمبوجیه مصر را فتح کرد. اگر آن نامه‌ی پنهان در شکم خرگوش نبود، شاید هیچ‌کدام از این‌ها اتفاق نمی‌افتاد.'
