      { name: 'والریانوس', desc: 'امپراتور روم در ۲۵۳–۲۶۰ میلادی. مردی سالخورده و محافظه‌کار.' },
      { name: 'کردیوس', desc: 'یکی از فرماندهان رومی که بعد از اسارت والریانوس، فرار کرد و در شرق خود را امپراتور خواند.' }
