        isHistorical: false,
        feedback: 'بر خلاف تبلیغات رومی، ساسانیان از توان فنی اسرای رومی برای ساخت شاهکارهای مهندسی آبی مانند سد شوشتر و بنیاد شهر جندی‌شاپور سود جستند. اگر شاپور تمام اسرا را اعدام می‌کرد، هم یک منبع بزرگ نیروی متخصص را از دست می‌داد و هم رومیان را به انتقام‌جویی بیشتر تحریک می‌کرد. خرد سیاسی شاپور در «استفاده از دشمن» بود، نه نابودی او.',
