    legacy:
      'شکست والریانوس، تأثیر عمیقی بر تاریخ دو امپراتوری گذاشت. در روم، این حادثه به «فاجعه‌ی ادسا» معروف شد و ضربه‌ای سنگین به غرور رومیان وارد کرد. اما در ایران، به عنوان نماد قدرت نظامی ساسانیان ثبت شد. برای قرن‌ها، شاهان ساسانی این پیروزی را به یاد می‌آوردند. مهندسان رومی اسیر، ساختار آبیاری خوزستان را متحول کردند. پل بند شوشتر، امروز یکی از بزرگ‌ترین شاهکارهای مهندسی آبی در جهان باستان شناخته می‌شود. دانشگاه جندی‌شاپور، که با کمک این اسرا بنیان نهاده شد، بعدها به کانون ترجمه‌ی متون یونانی به فارسی و از فارسی به عربی تبدیل شد.'
