    summary: 'پس از شاپور یکم، کرتیر موبد موبدان به قدرت رسید و با سرکوب آیین مانی و ادیان دیگر، دروازه‌های گفت‌وگو را برای همیشه بست.',
    iconKey: 'flame2',

    speakerA: { name: 'کرتیر', role: 'موبد موبدان و قدرتمندترین روحانی ساسانی', sigil: 'ک' },
    speakerB: { name: 'مانی', role: 'پیامبر و بنیان‌گذار آیین مانوی', sigil: 'م' },

    introduction:
      'شاپور یکم، برخلاف پدرش اردشیر، سیاست مدارای مذهبی را در پیش گرفته بود. در دربار او، هم موبدان زرتشتی، هم کاهنان مسیحی و یهودی، هم پیروان ادیان هندی و بودایی حضور داشتند. یکی از این مردان، «مانی» بود؛ پیامبری که آیین خود را آمیزه‌ای از زرتشت، مسیحیت و بودیسم معرفی می‌کرد. شاپور، مانی را گرامی می‌داشت و به او اجازه داد که در سراسر امپراتوری تبلیغ کند. اما پس از مرگ شاپور در ۲۷۰ میلادی، پسرش بهرام یکم به تخت نشست. کرتیر، موبد موبدان، به بهرام نزدیک شد و درخواست کرد که مانی محکوم شود.',

    characters: [
      { name: 'کرتیر', desc: 'موبد موبدان ساسانی. بلندپرواز، سیاستمدار و در پی انحصار دین زرتشتی.' },
      { name: 'مانی', desc: 'پیامبر ایرانی، بنیان‌گذار آیین مانوی. در بابل در حدود ۲۱۶ میلادی زاده شد.' },
      { name: 'بهرام یکم', desc: 'پادشاه ساسانی، پسر شاپور یکم. ابتدا تحت نفوذ موبدان بود، ولی بعدها به آن‌ها نزدیک شد.' }
    ],

    context:
      'سال ۲۷۵ میلادی است. مانی در دربار بهرام یکم احضار شده. پادشاه و موبدان موبد، در تالار بزرگ کاخ نشسته‌اند. مانی می‌داند که این احضار، ممکن است پایان زندگی‌اش باشد. اما همچنان امیدوار است که بتواند پادشاه را متقاعد کند که به سیاست مدارای مذهبی پدرش، شاپور یکم، برگردد. کرتیر در آن سوی تالار ایستاده و با نگاه سرد، مانی را می‌نگرد.',

    dialogue: [
      { speaker: 'مانی', text: 'ای شاه، آیین من آمیزه‌ای از حکمت زرتشت، مسیح و بوداست. من با هیچ دینی نمی‌جنگم؛ من می‌خواهم همه‌ی ادیان را به یک حقیقت یگانه برسانم.' },
      { speaker: 'کرتیر', text: 'ای شاه، این مرد آیین نیاکان را به باد مسخره گرفته و به نام پیامبری، سرزمین‌ها را به آتش کشیده است. اگر دست او باز بماند، آتش مقدس سرد و موبدان خوار خواهند شد.' },
      { speaker: 'مانی', text: 'من هرگز آتشی روشن نکرده‌ام. من هرگز کسی را نکشته‌ام. من فقط موعظه کرده‌ام و کتاب نوشته‌ام.' },
      { speaker: 'کرتیر', text: 'کتاب‌های تو، دل‌های جوانان را می‌دزدد. کتاب‌های تو، موبدان را بی‌اعتبار می‌کند. کتاب‌های تو، اهورامزدا را به حاشیه می‌راند.' },
      { speaker: 'بهرام', text: 'مانی، تو در زمان پدرم آزاد بودی. اما اکنون زمان تغییر است. دین رسمی ایران، زرتشتی است و باید باشد. من فرمان می‌دهم که تو از دربار بروی و تا زمانی که زنده‌ای، از تبلیغ آیین خود دست برداری.' },
      { speaker: 'مانی', text: 'من از تبلیغ آیین خود دست نخواهم کشید. اما همچنان امیدوارم که آیین من، روزی به دل‌های مردم راه یابد. حتی اگر من نباشم.' }
    ],

    dialogueQuote: '«ای شاه! این مرد آیین نیاکان را به باد مسخره گرفته. اگر دست او باز بماند، آتش مقدس سرد و موبدان خوار خواهند شد.»',

    sourceName: 'کتیبه‌ی کرتیر بر کعبه‌ی زرتشت & Encyclopaedia Iranica: "Mani, Manichaeism"',

    sourceDetails: 'کتیبه‌ی کرتیر یکی از بلندترین کتیبه‌های ساسانی است و در آن خود را «بنده‌ی مزداپرست» معرفی می‌کند و از سرکوب مسیحیان، مانویان، بوداییان و یهودیان سخن می‌گوید. مانی در ۲۷۷ میلادی به فرمان بهرام یکم به قتل رسید، اما مانوی‌گری تا سده‌ها در آسیا و اروپا گسترش یافت. کلیسای مانوی، به مدت هزار سال، از چین تا اسپانیا فعال بود. آگوستین قدیس، پیش از گرویدن به مسیحیت، مدت‌ها مانوی بود.',

