    introduction:
      'در سال ۱۰۳۷ میلادی، دودمانی ترک‌تبار از آسیای مرکزی به ایران حمله کرد: سلجوقیان. آن‌ها در نبرد دندانقان، غزنویان را شکست دادند و بر سراسر ایران مسلط شدند. سلجوقیان، ترک‌تبار و سنی‌مذهب بودند. اما درباریان آن‌ها، ایرانی بودند. یکی از این ایرانیان، «خواجه نظام‌الملک طوسی» بود؛ مردی از طوس، با استعداد فوق‌العاده در سیاست و ادب. او به وزیری «آلپ‌ارسلان» و سپس «ملکشاه» رسید و به مدت سی سال، قدرتمندترین مرد ایران پس از سلطان بود.',

    characters: [
      { name: 'خواجه نظام‌الملک', desc: 'وزیر دانشمند سلجوقی. مردی از طوس که به مدت سی سال در اوج قدرت بود.' },
      { name: 'ملکشاه سلجوقی', desc: 'سلطان بزرگ سلجوقی. در دوران او، امپراتوری سلجوقی به اوج قدرت رسید.' },
      { name: 'حسن صباح', desc: 'بنیان‌گذار فرقه‌ی اسماعیلیه‌ی الموت. دشمن سرسخت نظام‌الملک.' }
    ],

    context:
      'سال ۱۰۷۰ میلادی است. خواجه نظام‌الملک در دفتر خود در اصفهان نشسته. چند ماه پیش، اولین نظامیه را در بغداد بنیاد نهاده و حالا قصد دارد نظامیه‌های دیگری در نیشابور، اصفهان، هرات و بصره هم بسازد. یک فرستاده از سلطان ملکشاه آمده و می‌پرسد: چرا این همه پول برای ساختن مدارس؟ آیا می‌شود آن را در خزانه نگه داشت؟',

    dialogue: [
      { speaker: 'فرستاده', text: 'خواجه، سلطان می‌پرسد: چرا این همه پول برای ساختن مدارس؟ آیا این پول در خزانه بهتر نیست؟' },
      { speaker: 'نظام‌الملک', text: 'به سلطان بگو: حکومت بی دانش، چون پیکری بی‌جان است. اگر در هر شهر مدرسه‌ای بنا کنیم و دانشمندان را پناه دهیم، دانش نه از شرق می‌آید و نه از غرب؛ بلکه در دل همین خاک می‌روید.' },
      { speaker: 'فرستاده', text: 'اما سلطان می‌گوید که این کار، قدرت علما را زیاد می‌کند.' },
      { speaker: 'نظام‌الملک', text: 'بله. اما علما، اگر از ما پول بگیرند، به ما وفادار می‌شوند. و دانشمندی که در نظامیه‌ی ما درس خوانده، در آینده قاضی و مفتی و وزیر این مملکت می‌شود. این، بهترین سرمایه‌گذاری است.' },
      { speaker: 'فرستاده', text: 'پس می‌خواهی دین را به خدمت دولت درآوری؟' },
      { speaker: 'نظام‌الملک', text: 'نه، می‌خواهم دین و دولت، شریک باشند. دین به دولت مشروعیت می‌دهد، دولت به دین پول. اگر این پیوند محکم باشد، هیچ فرقه‌ای نمی‌تواند به ما ضربه بزند. حتی اسماعیلیه.' },
      { speaker: 'فرستاده', text: 'اما اسماعیلیه در الموت، خطر جدی است.' },
      { speaker: 'نظام‌الملک', text: 'می‌دانم. برای همین است که نظامیه‌ها را می‌سازم. اگر جوانان ما در نظامیه‌های ما درس بخوانند، به اسماعیلیه نمی‌پیوندند. ما باید پیش از فتح ذهن‌ها، مدرسه بسازیم، نه شمشیر.' }
    ],

    dialogueQuote: '«ای سلطان! حکومت بی دانش، چون پیکری بی‌جان است. اگر در هر شهر مدرسه‌ای بنا کنیم و دانشمندان را پناه دهیم، دانش نه از شرق می‌آید و نه از غرب؛ بلکه در دل همین خاک می‌روید.»',

    sourceName: 'سیاست‌نامه‌ی خواجه نظام‌الملک & The Cambridge History of Iran, Vol. 5',

    sourceDetails: 'نظامیه‌های بغداد و نیشابور به مهم‌ترین مراکز علمی جهان اسلام بدل شدند. امام محمد غزالی، بزرگ‌ترین متکلم و فیلسوف قرن پنجم هجری، در نظامیه‌ی بغداد تدریس کرد. نظام‌الملک همچنین کتاب «سیاست‌نامه» را نوشت که یکی از مهم‌ترین آثار اندیشه‌ی سیاسی ایران است. در سال ۱۰۹۲ میلادی، خواجه نظام‌الملک، در راه بغداد، به دست یک اسماعیلی مذهبی کشته شد.',

