        feedback: 'نادرست! نظامیه‌ها از همان آغاز بر پایه‌ی گفت‌وگوی علمی و تنوع رشته‌ها اداره می‌شدند. نظام‌الملک شخصاً با دانشمندان مختلف مکاتبه داشت. اگرچه نظامیه‌ها مدارس دینی بودند، اما در آن‌ها فقه، نجوم، ریاضیات، پزشکی و فلسفه تدریس می‌شد. بسیاری از دانشمندان بزرگ ایران، از جمله خواجه نصیرالدین طوسی در دوره‌ی بعد، در نظامیه‌ها درس خواندند.',
