        isHistorical: true,
        feedback: 'شاهکار مدیریت فرهنگی! این نظام آموزشی، الگویی برای مدارس دوره‌های بعدی شد و بستر رشد خواجه نصیرالدین طوسی و دیگران را فراهم ساخت. نظامیه‌ها، نخستین شبکه‌ی دانشگاهی سراسری در تاریخ ایران بودند. هزینه‌ی تحصیل و خوابگاه و خوراک دانشجویان، از سوی موقوفات تأمین می‌شد. این نوآوری، بعدها در ساختار دانشگاه‌های اروپایی هم اثر گذاشت. اگر امروز دانشگاه‌های جهان، بر پایه‌ی ساختار «مدرسه-کالج» کار می‌کنند، ریشه‌ی آن در نظامیه‌های خواجه نظام‌الملک است.',
