    dialogueQuote: '«شاه عباس: پایتخت را از قزوین به اصفهان می‌بریم؛ قلب زاینده‌رود در امان‌تر از مرزهای غرب است. انحصار تفنگ باید از دست سرکشان قزلباش خارج شود و لشکری از جوانان وفادار به دولت مرکزی برپا گردد.»',

    sourceName: 'Roger Savory: Iran Under the Safavids & عالم‌آرای عباسی',

    sourceDetails: 'شاه عباس با کمک مشاوران انگلیسی (برادران شرلی) ارتش تفنگدار و توپخانه ایجاد کرد، انحصار تجارت ابریشم را در دست گرفت و در سال ۱۶۲۲، با کمک ناوگان هند شرقی انگلیس، پرتغالی‌ها را از هرمز بیرون کرد. بندر گمبرون، به افتخار او، «بندرعباس» نام گرفت. میدان نقش جهان، مسجد شاه، عالی‌قاپو و چهل‌ستون، از یادگارهای معماری او هستند.',

